def build_msh(sender, receiver, msg_id):
    return '|'.join(['MSH', sender, receiver, msg_id])


def build_pid(pat_id, first_name, last_name):
    return '|'.join(['PID', pat_id, first_name, last_name])


def build_obr(order_id, test_code, date):
    return '|'.join(['OBR', order_id, test_code, date])


def build_obx(obs_id, value, units, ref_range):
    return '|'.join(['OBX', obs_id, value, units, ref_range])


def build_al1(allergy_type, allergen, severity):
    return '|'.join(['AL1', allergy_type, allergen, severity])


def build_dg1(diag_code, description, type_str):
    return '|'.join(['DG1', diag_code, description, type_str])


def build_evn(event_type, date, reason):
    return '|'.join(['EVN', event_type, date, reason])


def build_nte(source, comment, type_str):
    return '|'.join(['NTE', source, comment, type_str])


def format_name(first_name, last_name):
    return ''.join([last_name.upper(), '^', first_name])


def build_message(segments):
    return '\r'.join(segments)


def describe_message(segments):
    types = [segment.split('|')[0] for segment in segments]
    listed = ', '.join(types)
    return ''.join(['Message contains ', str(len(types)), ' segments: ', listed])


def main():
    patient_name = format_name('John', 'Doe')
    segments = [
        build_msh('LABSYS', 'HOSPITAL', 'MSG00001'),
        build_evn('A01', '20240115093000', 'ADMIT'),
        build_pid('PT12345', 'John', 'Doe'),
        build_obr('ORD98765', 'CBC^Complete Blood Count', '20240115094500'),
        build_obx('WBC^White Blood Cells', '7.2', '10*3/uL', '4.0-11.0'),
        build_al1('DA', 'Penicillin', 'SV'),
        build_dg1('J45.909', 'Unspecified asthma', 'A'),
        build_nte('L', 'Specimen collected fasting', 'GI'),
    ]
    print(''.join(['Patient: ', patient_name]))
    print(describe_message(segments))
    print(build_message(segments))


if __name__ == '__main__':
    main()

