def cron_time(minute, hour, dom, month, dow):
    return ' '.join([minute, hour, dom, month, dow])


def cron_env(key, value):
    return '='.join([key, value])


def cron_job(time_str, user, command):
    return ' '.join([time_str, user, command])


def cron_redirect(command, log_file):
    return ' > '.join([command, log_file])


def cron_append(command, log_file):
    return ' >> '.join([command, log_file])


def cron_mailto(email):
    return '='.join(['MAILTO', email])


def cron_path(paths_str):
    return '='.join(['PATH', paths_str])


def cron_shell(shell_bin):
    return '='.join(['SHELL', shell_bin])


def build_header(owner, generated_by):
    return '\n'.join([
        '# crontab for ' + owner,
        '# generated by ' + generated_by,
        '# m h dom mon dow user command',
    ])


def build_environment(shell_bin, paths, email):
    return '\n'.join([
        cron_shell(shell_bin),
        cron_path(':'.join(paths)),
        cron_mailto(email),
        cron_env('LANG', 'en_US.UTF-8'),
    ])


def main():
    paths = ['/usr/local/sbin', '/usr/local/bin', '/usr/sbin', '/usr/bin', '/sbin', '/bin']
    lines = [
        build_header('web-01', 'cronbuilder.py'),
        '',
        build_environment('/bin/bash', paths, 'ops@example.com'),
        '',
    ]

    nightly = cron_time('30', '2', '*', '*', '*')
    backup = ' '.join(['/usr/local/bin/backup.sh', '--target', '/srv/www'])
    lines.append(cron_job(nightly, 'root', cron_redirect(backup, '/var/log/backup.log')))

    quarter_hourly = cron_time('*/15', '*', '*', '*', '*')
    metrics = ' '.join(['/usr/local/bin/collect_metrics.py', '--quiet'])
    lines.append(cron_job(quarter_hourly, 'www-data', cron_append(metrics, '/var/log/metrics.log')))

    weekly = cron_time('0', '4', '*', '*', '7')
    rotate = ' '.join(['/usr/sbin/logrotate', '-f', '/etc/logrotate.conf'])
    lines.append(cron_job(weekly, 'root', cron_append(rotate, '/var/log/logrotate.log')))

    monthly = cron_time('5', '0', '1', '*', '*')
    report = ' '.join(['/usr/local/bin/report.py', '--month', '--mail', 'ops@example.com'])
    lines.append(cron_job(monthly, 'reports', cron_redirect(report, '/var/log/report.log')))

    print('\n'.join(lines))
    users = sorted({line.split()[5] for line in lines[4:]})
    print('# scheduled users: ' + ', '.join(users))


if __name__ == '__main__':
    main()

