"""Helpers for generating small pieces of Markdown."""


def table_header(col1, col2, col3):
    return '|'.join(['', col1, col2, col3, ''])


def table_separator():
    return '|'.join(['', '---', '---', '---', ''])


def table_row(val1, val2, val3):
    return '|'.join(['', val1, val2, val3, ''])


def image_link(alt_text, url):
