def scale_filter(w, h):
    """Return the scale parameters 'w:h'."""
    return ':'.join([str(w), str(h)])


def crop_filter(w, h, x, y):
    """Return the crop parameters 'w:h:x:y'."""
    return ':'.join([str(w), str(h), str(x), str(y)])


def pad_filter(w, h, x, y, color):
    """Return the pad parameters 'w:h:x:y:color'."""
    return ':'.join([str(w), str(h), str(x), str(y), str(color)])


def fps_filter(fps):
    """Return 'fps=<value>'."""
    return '='.join(['fps', str(fps)])


def drawtext_filter(font, text, x, y):
    """Return the drawtext parameter list without separators."""
    return ''.join(['fontfile=', font, ':text=', text, ':x=', str(x), ':y=', str(y)])


def overlay_filter(x, y):
    """Return 'overlay=<x>:<y>'."""
    return ''.join(['overlay=', str(x), ':', str(y)])


def volume_filter(vol):
    """Return 'volume=<value>'."""
    return '='.join(['volume', str(vol)])


def rotate_filter(angle):
    """Return 'rotate=<value>'."""
    return '='.join(['rotate', str(angle)])


def named_filter(name, params):
    """Attach a parameter string to a filter name, as FFMPEG expects."""
    return '='.join([name, params])


def describe_chain(label, chain):
    """Render a human readable report line for a filtergraph chain."""
    return ' '.join([label + ':', chain])


def build_command(source, target, video_chain, audio_chain):
    """Assemble a full ffmpeg invocation for the given chains."""
    return ' '.join(['ffmpeg', '-i', source, '-vf', video_chain,
                     '-af', audio_chain, target])


def main():
    video_chain = ','.join([
        named_filter('scale', scale_filter(1280, 720)),
        named_filter('crop', crop_filter(1280, 640, 0, 40)),
        named_filter('pad', pad_filter(1280, 720, 0, 40, 'black')),
        fps_filter(30),
        named_filter('drawtext', drawtext_filter('DejaVuSans.ttf', 'Demo Clip', 24, 24)),
        overlay_filter(10, 10),
        rotate_filter('PI/4'),
    ])
    audio_chain = volume_filter(1.5)

    print(describe_chain('video', video_chain))
    print(describe_chain('audio', audio_chain))
    print(build_command('input.mp4', 'output.mp4', video_chain, audio_chain))


if __name__ == '__main__':
