def move_basic(piece, square):
    return ''.join([piece, square])


def move_capture(piece, square):
    return 'x'.join([piece, square])


def move_check(move_str):
    return ''.join([move_str, '+'])


def move_mate(move_str):
    return ''.join([move_str, '#'])


def move_promotion(move_str, piece):
    return '='.join([move_str, piece])


def game_result(white_score, black_score):
    return '-'.join([white_score, black_score])


def nag_annotation(move_str, nag):
    return ' '.join([move_str, nag])


def castling_kingside(symbol1, symbol2):
    return '-'.join([symbol1, symbol2])


def tag_pair(name, value):
    return ''.join(['[', name, ' "', value, '"]'])


def numbered_move(number, white_move, black_move=None):
    label = ''.join([str(number), '.'])
    if black_move is None:
        return ' '.join([label, white_move])
    return ' '.join([label, white_move, black_move])


def movetext(moves, result):
    pairs = []
    for index in range(0, len(moves), 2):
        black_move = moves[index + 1] if index + 1 < len(moves) else None
        pairs.append(numbered_move(index // 2 + 1, moves[index], black_move))
    text = result
    for pair in reversed(pairs):
        text = ' '.join([pair, text])
    return text


def main():
    result = game_result('1', '0')
    castle = castling_kingside('O', 'O')
    check_move = move_check(move_basic('Q', 'h4'))
    mate_move = move_mate(move_capture('Q', 'f7'))
    promotion = move_promotion(move_basic('', 'e8'), 'Q')
    moves = [
        move_basic('', 'e4'),
        move_basic('', 'e5'),
        move_basic('N', 'f3'),
        move_basic('N', 'c6'),
        nag_annotation(move_capture('N', 'e5'), '!?'),
        castle,
        check_move,
        promotion,
        mate_move,
    ]
    tags = [
        ('Event', 'Sample Game'),
        ('White', 'Alice'),
        ('Black', 'Bob'),
        ('Result', result),
    ]
    for name, value in tags:
        print(tag_pair(name, value))
    print(movetext(moves, result))
    print(', '.join([castle, check_move, promotion, mate_move]))


if __name__ == '__main__':
    main()

