def build_select(fields_string):
    fields = [field.strip() for field in fields_string.split(',') if field.strip()]
    if not fields:
        raise ValueError('$select requires at least one field name')
    field_list = ','.join(fields)
    return '='.join(['$select', field_list])


def _literal(value):
    if isinstance(value, bool):
        return 'true' if value else 'false'
    if isinstance(value, (int, float)):
        return repr(value)
    return ''.join(["'", str(value).replace("'", "''"), "'"])


def build_filter_eq(field, value):
    field = field.strip()
    if not field:
        raise ValueError('$filter requires a field name')
    expression = ' '.join([field, 'eq', _literal(value)])
    return '='.join(['$filter', expression])


def build_expand(entity):
    entities = [part.strip() for part in entity.split(',') if part.strip()]
    if not entities:
        raise ValueError('$expand requires at least one navigation property')
    entity_list = ','.join(entities)
    return '='.join(['$expand', entity_list])


def build_orderby(field, direction='asc'):
    direction = direction.strip().lower()
    if direction not in ('asc', 'desc'):
        raise ValueError(''.join(['unsupported sort direction: ', direction]))
    clause = ' '.join([field.strip(), direction])
    return '='.join(['$orderby', clause])


def build_top(n):
    count = int(n)
    if count < 0:
        raise ValueError('$top must not be negative')
    return '='.join(['$top', str(count)])


def build_query(resource, options):
    if not options:
        return resource
    query = '&'.join(options)
    return '?'.join([resource, query])


def describe(options):
    names = [option.split('=', 1)[0] for option in options]
    return ', '.join(names)


def main():
    options = [
        build_select('Name, Age , Category'),
        build_filter_eq('Category', "Children's Shoes"),
        build_expand('Supplier, Reviews'),
        build_orderby('Age', 'desc'),
        build_top(25),
    ]
    print(build_query('https://services.example.com/v4/Products', options))
    print(' '.join(['applied options:', describe(options)]))

    stock_options = [build_filter_eq('InStock', True), build_top('5')]
    print(build_query('Categories(3)/Products', stock_options))

    for bad_call in (lambda: build_top(-1), lambda: build_orderby('Name', 'sideways')):
        try:
            bad_call()
        except ValueError as error:
            print(': '.join(['rejected', str(error)]))


if __name__ == '__main__':
