JMX_SPECIAL = set(':,="*?')


def _quote(value):
    """Quote an ObjectName property value if it contains reserved characters."""
    if not any(ch in JMX_SPECIAL for ch in value):
        return value
    escaped = ''
    for ch in value:
        if ch in '"*?\\':
            escaped += '\\'
        escaped += ch
    return ''.join(['"', escaped, '"'])


def _pair(key, value):
    """Render a single key=value property of an ObjectName."""
    if not key:
        raise ValueError('property key must not be empty')
    return '='.join([key, _quote(value)])


def _object_name(domain, properties):
    """Combine a validated domain, the colon separator and the property list."""
    if not domain:
        raise ValueError('domain must not be empty')
    for ch in domain:
        if ch in JMX_SPECIAL:
            raise ValueError(''.join(['illegal character ', ch, ' in domain ', domain]))
    return ''.join([domain, ':', properties])


def build_memory_mbean(pool_name):
    if pool_name is None:
        return _object_name('java.lang', _pair('type', 'Memory'))
    properties = ','.join([_pair('type', 'MemoryPool'), _pair('name', pool_name)])
    return _object_name('java.lang', properties)


def build_gc_mbean(gc_name):
    properties = ','.join([_pair('type', 'GarbageCollector'), _pair('name', gc_name)])
    return _object_name('java.lang', properties)


def build_thread_mbean():
    return _object_name('java.lang', _pair('type', 'Threading'))


def build_os_mbean():
    return _object_name('java.lang', _pair('type', 'OperatingSystem'))


def build_custom_mbean(domain, prop_key, prop_val):
    return _object_name(domain, _pair(prop_key, prop_val))


def describe(object_name):
    """Split an ObjectName back into its domain and property list."""
    domain, _, rest = object_name.partition(':')
    domain_field = ''.join(['domain=', domain])
    properties_field = ''.join(['properties=', rest])
    return ' '.join([domain_field, properties_field])


def format_row(object_name, width):
    return ' | '.join([object_name.ljust(width), describe(object_name)])


def main():
    names = [
        build_memory_mbean(None),
        build_memory_mbean('Metaspace'),
        build_memory_mbean('G1 Eden Space'),
        build_gc_mbean('G1 Young Generation'),
        build_thread_mbean(),
        build_os_mbean(),
        build_custom_mbean('com.example.app', 'service', 'order:processor'),
    ]
    width = max(len(name) for name in names)
    for name in names:
        print(format_row(name, width))
    print(''.join(['total mbeans: ', str(len(names))]))


if __name__ == '__main__':
    main()

