def _clean(label, value):
    if not isinstance(value, str) or not value:
        raise ValueError(''.join([label, " must be a non-empty string"]))
    for ch in value:
        if ch in _ILLEGAL:
            raise ValueError(''.join([label, " contains illegal character ", repr(ch)]))
    if value in (".", ".."):
        raise ValueError(''.join([label, " may not be '.' or '..'"]))
    return value


