def encrypt_alg(alg, key_len):
    """Return an encryption transform name such as 'aes256' or 'aes128gcm16'."""
    base = alg.strip().lower()
    length = key_len.strip()
    if not base:
        raise ValueError("encryption algorithm must not be empty")
    if base.endswith(length):
        return base
    return ''.join([base, length])


def integ_alg(alg):
    """Return an integrity transform name such as 'sha384'."""
    name = alg.strip().lower()
    if not name:
        raise ValueError("integrity algorithm must not be empty")
    return name


def dh_group(group):
    """Return a Diffie-Hellman group name, adding the 'modp' prefix for bare bit sizes."""
    name = group.strip().lower()
    if name.isdigit():
        return ''.join(['modp', name])
    return name


def prf_alg(alg):
    """Return a PRF transform name, adding the 'prf' prefix when it is missing."""
    name = alg.strip().lower()
    if name.startswith('prf'):
        return name
    return ''.join(['prf', name])


def full_proposal(enc, integ, prf, dh):
    return '-'.join([enc, integ, prf, dh])


def esp_proposal(enc, integ, dh):
    return '-'.join([enc, integ, dh])


def ah_proposal(integ, dh):
    return '-'.join([integ, dh])


def ike_sa_proposal(enc, prf, dh):
    return '-'.join([enc, prf, dh])


def describe_suite(name, enc, integ, prf, dh):
    """Render one strongSwan connection block for the given transform set."""
    lines = [
        ''.join(['conn ', name]),
        '    keyexchange = ikev2',
        ''.join(['    ike = ', full_proposal(enc, integ, prf, dh)]),
        ''.join(['    esp = ', esp_proposal(enc, integ, dh)]),
        ''.join(['    ah = ', ah_proposal(integ, dh)]),
    ]
    return '\n'.join(lines)


def main():
    suites = [
        ('high', 'aes', '256', 'sha384', 'sha384', '3072'),
        ('default', 'aes', '128', 'sha256', 'prfsha256', 'modp2048'),
    ]
    blocks = []
    for name, cipher, bits, integrity, prf, group in suites:
        enc = encrypt_alg(cipher, bits)
        integ = integ_alg(integrity)
        pseudo = prf_alg(prf)
        dh = dh_group(group)
        transforms = ', '.join([enc, integ, pseudo, dh])
        print(''.join(['# ', name, ' transforms: ', transforms]))
        print(''.join(['# ', name, ' ike_sa: ', ike_sa_proposal(enc, pseudo, dh)]))
        blocks.append(describe_suite(name, enc, integ, pseudo, dh))
    print('\n\n'.join(blocks))


if __name__ == '__main__':
    main()

