    return _require_digits("asn", asn) + ':' + _require_digits("val", val)


def ext_route_target(asn, val):
    """Return an extended route-target community such as "rt:65001:300"."""
    return "rt" + ':' + _require_digits("asn", asn) + ':' + _require_digits("val", val)


def ext_route_origin(asn, val):
    """Return an extended route-origin community such as "ro:65001:301"."""
    return "ro" + ':' + _require_digits("asn", asn) + ':' + _require_digits("val", val)


def large_community(asn, local_data1, local_data2):
    """Return a large community such as "65000:100:200"."""
    return (
        _require_digits("asn", asn) + ':' +
        _require_digits("local_data1", local_data1) + ':' +
        _require_digits("local_data2", local_data2)
    )


def link_bw(asn, bw):
    """Return a link-bandwidth extended community."""
    return "link-bandwidth" + ':' + _require_digits("asn", asn) + ':' + _require_digits("bw", bw)


def soo(asn, val):
    """Return a site-of-origin extended community."""
    return "soo" + ':' + _require_digits("asn", asn) + ':' + _require_digits("val", val)


def ipv6_ext(ipv6, val):
    """Return an IPv6 extended community such as "2001:db8::1:123"."""
    if ':' not in ipv6:
        raise ValueError("ipv6 must contain ':', got " + repr(ipv6))
    return ipv6 + ':' + _require_digits("val", val)


def well_known(name):
    """Return the numeric encoding of a well-known community name."""
    key = name.strip().lower()
    if key not in WELL_KNOWN:
        raise ValueError("unknown well-known community " + repr(name))
    return WELL_KNOWN[key]


def describe(label, community):
    """Render one report row as "label -> community"."""
    return label.ljust(16) + ' -> ' + community


def build_policy(asn):
    """Return the community set applied to routes originated by *asn*."""
    return [
        ("standard", std_community(asn, "100")),
        ("route-target", ext_route_target(asn, "300")),
        ("route-origin", ext_route_origin(asn, "301")),
        ("large", large_community(asn, "100", "200")),
        ("link-bandwidth", link_bw(asn, "1000")),
        ("site-of-origin", soo(asn, "7")),
        ("ipv6-extended", ipv6_ext("2001:db8::1", "123")),
        ("well-known", well_known("no-export")),
    ]


def main():
    asn = "65000"
    print("policy for AS" + asn + ":")
    for label, community in build_policy(asn):
        print(describe(label, community))
        print("  set community" + ' ' + community + ' ' + "additive")


if __name__ == "__main__":
    main()

