def render_report(rows):
    """Turn (label, identifier) pairs into an aligned multi-line report."""
    width = max(len(label) for label, _ in rows)
    report = ''
    for label, value in rows:
        report += label.ljust(width) + '  ' + value + '\n'
    return report


def main():
    rows = [
        ('geometry', geom_absolute("800", "600", "100", "50")),
        ('geometry%', geom_relative("800", "600", "10", "20")),
        ('WM_CLASS', win_title("URxvt", "urxvt", "Terminal")),
        ('_NET_WM_STATE', win_state("MAXIMIZED_VERT", "MAXIMIZED_HORZ", "HIDDEN")),
        ('_MOTIF_WM_HINTS', win_motif("ALL", "RESIZE", "MODELESS")),
        ('_NET_WM_PID', win_pid_machine("4211", "workstation")),
        ('xrandr', xrandr_out("HDMI-1", "1920x1080", "60", "+0+0")),
        ('xprop', xprop_atom("_NET_WM_NAME", "UTF8_STRING", "Editor")),
    ]
    print(render_report(rows), end='')
    print('properties built: ' + str(len(rows)))
    try:
        xrandr_out("DP-2", "2560x1440", "  ", "")
    except ValueError as err:
        print('rejected: ' + str(err))


if __name__ == '__main__':
    main()

