"""Generate JSONPath expressions from basic string components."""

_NAME_EXTRA = "_-@"


def _validate_name(name):
    """Reject empty names and names holding characters JSONPath cannot use bare."""
    if not name:
        raise ValueError("segment name must not be empty")
    for char in name:
        if not (char.isalnum() or char in _NAME_EXTRA):
            raise ValueError("".join(["illegal character ", repr(char), " in ", repr(name)]))
    return name


def build_root():
    return "$"


def build_child(parent, child):
    return "".join([parent, ".", _validate_name(child)])


def build_descendant(parent, child):
    return "".join([parent, "..", _validate_name(child)])


def build_index(path, idx):
    return "".join([path, "[", str(idx), "]"])


def build_slice(path, start, end):
    return "".join([path, "[", str(start), ":", str(end), "]"])


def build_filter(path, expr):
    return "".join([path, "[?(", expr, ")]"])


def build_script(path, script):
    return "".join([path, "[((", script, "))]"])


def build_wildcard(path):
    return "".join([path, ".*"])


def build_condition(field, operator, value):
    """Compose a filter expression body such as @.price < 10."""
    return " ".join([build_child("@", field), operator, str(value)])


def describe(label, path):
    """Render one report line: a label plus the generated path."""
    return "".join([label.ljust(12), ": ", path])


def main():
    root = build_root()
    store = build_child(root, "store")
    books = build_child(store, "book")
    cheap = build_filter(books, build_condition("price", "<", 10))
    last = build_script(books, "".join([build_child("@", "length"), "-1"]))
    print(describe("root", build_wildcard(root)))
    print(describe("child", books))
    print(describe("descendant", build_descendant(root, "author")))
    print(describe("indexed", build_index(books, 0)))
    print(describe("sliced", build_slice(books, 1, 3)))
    print(describe("filtered", cheap))
    print(describe("scripted", last))
    query = build_child(build_index(cheap, 0), "title")
    print("".join(["full query -> ", query]))


if __name__ == "__main__":
    main()

