_SPECIAL = set(',+"\\<>;=')


def escape_value(val):
    """Escape a value according to the RFC 4514 rules for DN string encoding."""
    if not isinstance(val, str):
        raise TypeError("RDN values must be strings")
    pieces = []
    last = len(val) - 1
    for index, char in enumerate(val):
        if char in _SPECIAL or char == '#' and index == 0:
            pieces.append('\\' + char)
        elif char == ' ' and index in (0, last):
            pieces.append('\\ ')
        else:
            pieces.append(char)
    return ''.join(pieces)


def rdn_country(val):
    code = val.strip()
    if len(code) != 2 or not code.isalpha():
        raise ValueError("country code must be two letters, got %r" % (val,))
    return '='.join(['C', escape_value(code.upper())])


def rdn_organization(val):
    return '='.join(['O', escape_value(val)])


def rdn_org_unit(val):
    return '='.join(['OU', escape_value(val)])


def rdn_common_name(val):
    return '='.join(['CN', escape_value(val)])


def rdn_locality(val):
    return '='.join(['L', escape_value(val)])


def rdn_state(val):
    return '='.join(['ST', escape_value(val)])


def rdn_email(val):
    return '='.join(['EMAIL', escape_value(val)])


def rdn_domain_component(val):
    return '='.join(['DC', escape_value(val)])


def build_subject(rdns):
    """Join RDNs into a comma separated X.509 subject string."""
    return ', '.join(rdns)


def openssl_subject(rdns):
    """Render the same RDNs in the slash separated form used by OpenSSL."""
    return '/' + '/'.join(rdns)


def describe(rdns):
    rows = []
    for number, rdn in enumerate(rdns, 1):
        key, value = rdn.split('=', 1)
        rows.append(' '.join(['%2d.' % number, key.ljust(6), value]))
    return '\n'.join(rows)


def main():
    sample = {
        'country': 'us',
        'state': 'California',
        'locality': 'Mountain View',
        'organization': 'Example, Inc.',
        'org_unit': 'IT Department',
        'common_name': 'www.example.com',
        'email': 'admin@example.com',
        'domain': 'www.example.com',
    }
    rdns = [
        rdn_country(sample['country']),
        rdn_state(sample['state']),
        rdn_locality(sample['locality']),
        rdn_organization(sample['organization']),
        rdn_org_unit(sample['org_unit']),
        rdn_common_name(sample['common_name']),
        rdn_email(sample['email']),
    ]
    rdns.extend(rdn_domain_component(part) for part in sample['domain'].split('.'))
    print('Generated RDNs:')
