def urdf_joint(name, joint_type):
    return ''.join(['<joint name=', _quote(name),
                    ' type=', _quote(joint_type), '>'])


def urdf_parent(link):
    return ''.join(['<parent link=', _quote(link), '/>'])


def urdf_child(link):
    return ''.join(['<child link=', _quote(link), '/>'])


def urdf_origin(xyz, rpy):
    return ''.join(['<origin xyz=', _quote(_as_text(xyz)),
                    ' rpy=', _quote(_as_text(rpy)), '/>'])


def urdf_mass(value):
    return ''.join(['<mass value=', _quote(value), '/>'])


def urdf_box(size):
    return ''.join(['<box size=', _quote(_as_text(size)), '/>'])


def urdf_cylinder(radius, length):
    return ''.join(['<cylinder radius=', _quote(radius),
                    ' length=', _quote(length), '/>'])


def urdf_comment(text):
    return ''.join(['<!-- ', text, ' -->'])


