import re

INDENT = "  "


def gem_source(url):
    return ''.join(["source '", url, "'"])


def gem_basic(name):
    return ''.join(["gem '", name, "'"])


def gem_version(name, version):
    return ''.join(["gem '", name, "', '", version, "'"])


def gem_github(name, repo):
    return ''.join(["gem '", name, "', github: '", repo, "'"])


def gem_branch(name, repo, branch):
    return ''.join([gem_github(name, repo), ", branch: '", branch, "'"])


def gem_group(group_name):
    return ''.join(["group :", group_name, " do"])


def gem_require_false(name):
    return ''.join([gem_basic(name), ", require: false"])


def gem_path(name, path):
    return ''.join([gem_basic(name), ", path: '", path, "'"])


def group_block(group_name, declarations):
    lines = [gem_group(group_name)]
    for declaration in declarations:
        lines.append(''.join([INDENT, declaration]))
    lines.append("end")
    return lines


def render_gemfile(sections):
    chunks = []
    for section in sections:
        if isinstance(section, str):
            chunks.append(section)
        else:
            chunks.append('\n'.join(section))
    return '\n\n'.join(chunks)


def declared_gems(gemfile_text):
    names = []
    for match in re.finditer(r"^\s*gem '([^']+)'", gemfile_text, re.M):
        names.append(match.group(1))
    return names


def main():
    sections = [
        gem_source("https://rubygems.org"),
        [
            gem_version("rails", "7.1.3"),
            gem_basic("puma"),
            gem_github("devise", "heartcombo/devise"),
            gem_branch("sidekiq", "sidekiq/sidekiq", "main"),
            gem_require_false("bootsnap"),
            gem_path("house_style", "vendor/house_style"),
        ],
        group_block("development", [gem_basic("web-console"), gem_version("listen", "3.8.0")]),
        group_block("test", [gem_basic("rspec-rails"), gem_require_false("simplecov")]),
    ]
    gemfile_text = render_gemfile(sections)
    print(gemfile_text)
    names = declared_gems(gemfile_text)
    print()
    print(''.join(["# ", str(len(names)), " gems declared"]))
    inventory = ', '.join(sorted(names))
    print(''.join(["# ", inventory]))


if __name__ == "__main__":
    main()

