def bicep_param(name, type):
    return ''.join(['param ', name, ' ', type])


def bicep_param_default(name, type, val):
    return ''.join(['param ', name, ' ', type, ' = ', val])


def bicep_var(name, val):
    return ''.join(['var ', name, ' = ', val])


def bicep_resource(name, type, api):
    return ''.join(['resource ', name, " '", type, '@', api, "' = {"])


def bicep_location(loc):
    return ''.join(['location: ', loc])


def bicep_sku(name):
    return ''.join(["sku: { name: '", name, "' }"])


def bicep_depends_on(res):
    if isinstance(res, (list, tuple)):
        res = ', '.join(res)
    return ''.join(['dependsOn: [ ', res, ' ]'])


def bicep_output(name, type, val):
    return ''.join(['output ', name, ' ', type, ' = ', val])


def indent_block(lines, level=1):
    pad = '  ' * level
    return [''.join([pad, line]) for line in lines]


def resource_block(name, type, api, body):
    return [bicep_resource(name, type, api)] + indent_block(body) + ['}']


def render(sections):
    blocks = ['\n'.join(section) for section in sections]
    return '\n\n'.join(blocks)


def main():
    params = [
        bicep_param('location', 'string'),
        bicep_param_default('storageName', 'string', "'stcontoso001'"),
        bicep_param_default('skuName', 'string', "'Standard_LRS'"),
    ]
    variables = [
        bicep_var('tags', "{ env: 'prod' }"),
        bicep_var('planName', "'${storageName}-plan'"),
    ]
    specs = [
        ('stg', 'Microsoft.Storage/storageAccounts', '2023-01-01', [
            'name: storageName',
            bicep_location('location'),
            bicep_sku('Standard_LRS'),
            "kind: 'StorageV2'",
            'tags: tags',
        ]),
        ('plan', 'Microsoft.Web/serverfarms', '2022-09-01', [
            'name: planName',
            bicep_location('location'),
            bicep_sku('B1'),
            bicep_depends_on(['stg']),
        ]),
    ]
    outputs = [
        bicep_output('storageId', 'string', 'stg.id'),
        bicep_output('planId', 'string', 'plan.id'),
    ]
    sections = [params, variables]
    sections.extend(resource_block(*spec) for spec in specs)
    sections.append(outputs)
    print(render(sections))
    names = ', '.join(name for name, _type, _api, _body in specs)
    print(''.join(['// declared resources: ', names]))


if __name__ == '__main__':
    main()

