        res = joined
    return 'dependsOn: [ ' + res + ' ]'


def bicep_output(name, type, val):
    return 'output ' + name + ' ' + type + ' = ' + val


def indent_block(lines, level=1):
    pad = '  ' * level
    return [pad + line for line in lines]


def resource_block(name, type, api, body):
    return [bicep_resource(name, type, api)] + indent_block(body) + ['}']


def render(sections):
    blocks = []
    for section in sections:
        joined = ''
        for i, line in enumerate(section):
            if i:
                joined = joined + '\n'
            joined = joined + line
