)


def format_reference(database, accession, locus):
    return ''.join([database, '|', accession, '|', locus])


def format_source(organism, strain, isolate):
    return ''.join([organism, ' ', strain, ' ', isolate])


def format_location(chromosome, arm, band):
    return ''.join([chromosome, '-', arm, '-', band])


def format_transcript(gene, protein, exon):
    return ''.join([gene, '/', protein, '/', exon])


def _validate(index, sequence):
    if len(sequence) != 12:
        raise ValueError(''.join([
            'sequence ', str(index), ' must hold 12 fields, got ', str(len(sequence)),
        ]))
    for name, value in zip(FIELD_NAMES, sequence):
        if not value.strip():
            raise ValueError(''.join([
                'sequence ', str(index), ' has an empty ', name, ' field',
            ]))


def fasta(sequences):
    records = []
    for index, sequence in enumerate(sequences):
        _validate(index, sequence)
        (database, accession, locus,
         organism, strain, isolate,
         chromosome, arm, band,
         gene, protein, exon) = sequence
        records.append((
            format_reference(database, accession, locus),
            format_source(organism, strain, isolate),
            format_location(chromosome, arm, band),
            format_transcript(gene, protein, exon),
            ''.join([database, ':', organism]),
            ''.join([accession, ':', strain]),
            ''.join([locus, ':', isolate]),
            ''.join([chromosome, '+', gene]),
        ))
    return records


def describe(index, record):
    links = ', '.join(record[4:])
    lines = [''.join(['>record ', str(index), ' ', record[0]])]
    lines.append(''.join(['  source:     ', record[1]]))
    lines.append(''.join(['  location:   ', record[2]]))
    lines.append(''.join(['  transcript: ', record[3]]))
    lines.append(''.join(['  links:      ', links]))
    return lines


