    "weft_fiber", "weft_thickness", "finish", "width",
)


def _validate(bolt, index):
    if len(bolt) != 9:
        raise ValueError(''.join(["bolt ", str(index), " needs 9 fields, got ", str(len(bolt))]))
    for name, value in zip(FIELDS, bolt):
        if not str(value).strip():
            raise ValueError(''.join(["bolt ", str(index), " has an empty field: ", name]))


def _base_code(bolt):
    mill, weave, dye_lot, warp_fiber, warp_th, weft_fiber, weft_th, finish, width = bolt
    source_block = '-'.join([mill, weave, dye_lot])
    yarn_block = '/'.join([warp_fiber, warp_th, weft_fiber])
    spec_block = '_'.join([weft_th, finish, width])
    return ' '.join([source_block, yarn_block, spec_block])


def _jacquard_code(bolt, base):
    mill, weave, dye_lot, warp_fiber, warp_th, weft_fiber, weft_th, finish = bolt[:8]
    luxury_prefix = ':'.join(["premium", mill, weave])
    pattern_block = '&'.join([dye_lot, warp_fiber, warp_th])
    special_finish = '+'.join([weft_fiber, weft_th, finish])
    return '|'.join([luxury_prefix, pattern_block, special_finish, base])


def textile(bolts):
    codes = []
    for index, bolt in enumerate(bolts):
        _validate(bolt, index)
        normalized = tuple(str(field).strip() for field in bolt)
        base = _base_code(normalized)
        if normalized[1].lower() == "jacquard":
            codes.append(_jacquard_code(normalized, base))
        else:
            codes.append(base)
    return codes


def catalog_lines(bolts):
    codes = textile(bolts)
    lines = ["FABRIC CATALOG", '=' * 14]
    for bolt, code in zip(bolts, codes):
        header = ', '.join([str(bolt[0]), str(bolt[1]), str(bolt[8])])
        lines.append(''.join(["* ", header]))
        lines.append(''.join(["    ", code]))
    lines.append(''.join(["total bolts: ", str(len(codes))]))
    return lines


