WIDE_THRESHOLD = 1.0

FIELD_NAMES = (
    "cave system", "entrance name", "survey date", "survey station",
    "compass bearing", "inclination angle", "passage width",
    "passage height", "geology type",
)


def _blocks(survey):
    system, entrance, date, station, bearing, angle, width, height, geology = survey
    surface = '-'.join([str(system), str(entrance), str(date)])
    vector = ':'.join([str(station), str(bearing), str(angle)])
    environment = '/'.join([str(width), str(height), str(geology)])
    return surface, vector, environment


def _width_in_metres(width):
    text = str(width).strip().lower()
    number_text = ""
    for char in text:
        if char.isdigit() or char in ".-":
            number_text += char
        else:
            break
    if not number_text.strip(".-"):
        raise ValueError("unrecognised passage width: %s" % text)
    number = float(number_text)
    if text.endswith("cm"):
        return number / 100.0
    return number


def _validate(survey, index):
    if len(survey) != 9:
        raise ValueError("survey %d has %d fields, expected 9" % (index, len(survey)))
    for name, value in zip(FIELD_NAMES, survey):
        if not str(value).strip():
            raise ValueError("survey %d has an empty %s" % (index, name))


def speleology(surveys):
    logged = []
    for index, survey in enumerate(surveys, start=1):
        _validate(survey, index)
        system, entrance, date, station, bearing, angle, width, height, geology = survey
        surface, vector, environment = _blocks(survey)
        base = ' '.join([surface, vector, environment])
        if _width_in_metres(width) >= WIDE_THRESHOLD:
            logged.append(base)
            continue
        squeeze = '_'.join(["crawl", str(system), str(entrance)])
        hazard = '+'.join([str(date), str(station), str(bearing)])
        deep = 'x'.join([str(angle), str(width), str(height)])
        logged.append('|'.join([squeeze, hazard, deep, base]))
    return logged


def format_report(surveys):
    lines = []
    for number, (survey, entry) in enumerate(zip(surveys, speleology(surveys)), start=1):
        label = ', '.join([str(number), str(survey[0]), str(survey[3])])
        lines.append("[%s] %s" % (label, entry))
    return lines


def main():
