def build_firewall_key(payload):
    return '-'.join([payload['protocol'], payload['port'], payload['hash']])

def build_mainframe_key(payload):
    return '/'.join([payload['node'], payload['cluster'], payload['thread']])

def build_database_key(payload):
    return ':'.join([payload['table'], payload['row'], payload['column']])

def build_user_key(payload):
    return '.'.join([payload['alias'], payload['clearance'], payload['retina']])

def build_subsystem_key(payload):
    return '+'.join([payload['power'], payload['cooling'], payload['ventilation']])

def build_camera_key(payload):
    return ', '.join([payload['feed'], payload['angle'], payload['filter']])

def build_drone_key(payload):
    return ' '.join([payload['model'], payload['altitude'], payload['weapon']])

def build_vault_key(payload):
    return '->'.join([payload['biometric'], payload['keypad'], payload['voice']])

def slice(terminals):
    overrides = []
    processors = {
        'firewall': build_firewall_key,
        'mainframe': build_mainframe_key,
        'database': build_database_key,
        'user': build_user_key,
        'subsystem': build_subsystem_key,
        'camera': build_camera_key,
        'drone': build_drone_key,
        'vault': build_vault_key
    }

    for payload in terminals:
        node_type = payload.get('type')
        if node_type in processors:
            try:
                override_string = processors[node_type](payload)
                overrides.append(override_string)
            except KeyError:
                continue
            except TypeError:
                continue

    return overrides

