    return '-'.join([score['composer'], score['opus'], score['key']])


def string_section(score):
    return '/'.join([score['violin'], score['viola'], score['cello']])


def woodwind_section(score):
    return ', '.join([score['flute'], score['oboe'], score['bassoon']])


def brass_section(score):
    return ':'.join([score['trumpet'], score['horn'], score['tuba']])


def percussion_section(score):
    return '.'.join([score['timpani'], score['snare'], score['cymbal']])


def tempo_line(score):
    return '+'.join([score['marking'], str(score['bpm']), score['rubato']])


def dynamics_line(score):
    return ' '.join([score['crescendo'], score['forte'], score['piano']])


def conductor_notes(score):
    return ' -> '.join([score['expression'], score['cue'], score['fermata']])


def arrange(scores):
    catalog = []
    for score in scores:
        entry = ' | '.join([
            symphony_line(score),
            string_section(score),
            woodwind_section(score),
            brass_section(score),
            percussion_section(score),
            tempo_line(score),
            dynamics_line(score),
            conductor_notes(score),
