RECIPE_ARROW = '->'


def healing_draught(cauldron):
    return '-'.join([cauldron['herb'], cauldron['water'], cauldron['bandage']])


def invisibility_serum(cauldron):
    return '/'.join([cauldron['mist'], cauldron['shadow'], cauldron['mirror']])


def love_filter(cauldron):
    return ', '.join([cauldron['petal'], cauldron['tear'], cauldron['honey']])


def strength_tonic(cauldron):
    return ':'.join([cauldron['root'], cauldron['iron'], cauldron['blood']])


def sleep_potion(cauldron):
    return '.'.join([cauldron['poppy'], cauldron['dream'], cauldron['dust']])


def truth_serum(cauldron):
    return '+'.join([cauldron['feather'], cauldron['scale'], cauldron['crystal']])


def poison_vial(cauldron):
    return ' '.join([cauldron['venom'], cauldron['thorn'], cauldron['ash']])


def transformation_brew(cauldron):
    return RECIPE_ARROW.join([cauldron['hair'], cauldron['moon'], cauldron['clay']])


RECIPES = [
    ('healing draught', ('herb', 'water', 'bandage'), healing_draught),
    ('invisibility serum', ('mist', 'shadow', 'mirror'), invisibility_serum),
    ('love filter', ('petal', 'tear', 'honey'), love_filter),
    ('strength tonic', ('root', 'iron', 'blood'), strength_tonic),
    ('sleep potion', ('poppy', 'dream', 'dust'), sleep_potion),
    ('truth serum', ('feather', 'scale', 'crystal'), truth_serum),
    ('poison vial', ('venom', 'thorn', 'ash'), poison_vial),
    ('transformation brew', ('hair', 'moon', 'clay'), transformation_brew),
]


def identify(cauldron, index):
    for name, keys, mixer in RECIPES:
        present = [key for key in keys if key in cauldron]
        if len(present) == len(keys):
            return name, mixer
        if present:
            raise ValueError(f'cauldron {index} resembles the {name} but is incomplete')
    raise ValueError(f'cauldron {index} matches no known recipe')


def brew(cauldrons):
    return [identify(cauldron, index)[1](cauldron) for index, cauldron in enumerate(cauldrons)]


def report(cauldrons):
    lines = []
    for index, (cauldron, text) in enumerate(zip(cauldrons, brew(cauldrons))):
        name = identify(cauldron, index)[0]
        lines.append(f'{name}: {text}')
    return lines


def main():
    cauldrons = [
        {'herb': 'sage', 'water': 'spring', 'bandage': 'linen'},
        {'mist': 'dawn', 'shadow': 'oak', 'mirror': 'silver'},
        {'petal': 'rose', 'tear': 'joy', 'honey': 'clover'},
