    for note in targets:
        patrol = format_guard_patrol(note)
        vault = format_vault_lock(note)
        alarm = format_alarm_system(note)
        vehicle = format_getaway_vehicle(note)
        disguise = format_disguise(note)
        laser = format_laser_grid(note)
        safe = format_safe_cracking(note)
        distraction = format_distraction(note)

        compiled_parts = [patrol, vault, alarm, vehicle, disguise, laser, safe, distraction]
        full_instruction = ' | '.join(compiled_parts)
        instructions.append(full_instruction)

    return instructions

def _require(stats, keys):
    missing = [key for key in keys if not str(stats.get(key, '')).strip()]
    if missing:
        detail = ', '.join(missing)
        raise ValueError(''.join(['incomplete athlete stats, missing: ', detail]))
    return [str(stats[key]).strip() for key in keys]


