MISSING = 'to be announced'

TOPICS = (
    ('movies', 'Now Showing'),
    ('early', 'Early Showtimes'),
    ('late', 'Late Showtimes'),
    ('snacks', 'Snack Specials'),
    ('tiers', 'Ticket Tiers'),
    ('trailers', 'Coming Attractions'),
    ('zones', 'Seating Zones'),
    ('exits', 'Emergency Exits'),
)


def _entries(raw):
    if raw is None:
        return []
    return [str(item).strip() for item in raw if str(item).strip()]


def _marquee(titles):
    items = _entries(titles)
    if not items:
        return MISSING
    return ' | '.join(items)


def _showtimes(times):
    stamps = _entries(times)
    if not stamps:
        return MISSING
    return ', '.join(stamps)


def _listing(items):
    values = _entries(items)
    if not values:
        return MISSING
    return ','.join(values)


def _check_keys(theater):
    absent = [key for key, _ in TOPICS if key not in theater]
    if absent:
        raise ValueError('missing schedule data for: ' + ', '.join(absent))


def cinema(theater):
    _check_keys(theater)
    lines = [
        'Now Showing: ' + _marquee(theater['movies']),
        'Early Showtimes: ' + _showtimes(theater['early']),
        'Late Showtimes: ' + _showtimes(theater['late']),
        'Snack Specials: ' + _listing(theater['snacks']),
        'Ticket Tiers: ' + _listing(theater['tiers']),
        'Coming Attractions: ' + _marquee(theater['trailers']),
        'Seating Zones: ' + _listing(theater['zones']),
        'Emergency Exits: ' + _listing(theater['exits']),
    ]
    return '\n'.join(lines)


def daily_digest(theaters):
    blocks = [cinema(theater) for theater in theaters]
