def _clean(items):
    return [str(item).strip() for item in items if str(item).strip()]


def _commas(items):
    return ', '.join(_clean(items)) or 'NONE ON RECORD'


def _route(items):
    steps = _clean(items)
    if not steps:
        return 'NONE ON RECORD'
    return ' -> '.join(steps)


def _header(agent):
    codename = str(agent.get('codename', 'UNKNOWN')).strip().upper()
    clearance = str(agent.get('clearance', 'UNCLASSIFIED')).strip().upper()
    title = ' '.join(['DOSSIER:', codename])
    return [title, ''.join(['CLEARANCE LEVEL: ', clearance]), '=' * len(title)]


def _threat_summary(levels):
    ranks = _clean(levels)
    if not ranks:
        return 'Threat Levels: UNASSESSED'
    label = ', '.join(ranks)
    return ''.join(['Threat Levels: ', label, ' (peak: ', ranks[-1], ')'])


def _linguistics(languages):
    spoken = _clean(languages)
    listing = _commas(spoken)
    if len(spoken) > 1:
        return ''.join(['Languages: ', listing, ' -- polyglot flag set'])
    return ''.join(['Languages: ', listing])


def _inventory(gadgets):
    issued = _clean(gadgets)
    if not issued:
        return 'Gadget Inventory: NONE ISSUED'
    listing = _commas(issued)
    return ''.join(['Gadget Inventory: ', listing, ' (', str(len(issued)), ' items)'])


def dossier(agent):
    lines = _header(agent)
    lines.append(''.join(['Known Aliases: ', _commas(agent.get('aliases', []))]))
    lines.append(''.join(['Past Associates: ', _commas(agent.get('associates', []))]))
    lines.append(_linguistics(agent.get('languages', [])))
