        'private_donors': ['Reyes Family Trust', 'Blue Horizon Fund'],
        'conservation_messages': ['Choose sustainable seafood', 'Refuse single-use plastic'],
        'restricted_areas': ['quarantine lab', 'pump gallery'],
    }
    print(exhibit(aquarium))


if __name__ == '__main__':
    main()

