def _arrow_path(stops):
    return ' -> '.join(stop.strip() for stop in stops if stop.strip())


def _listing(items):
    return ', '.join(item.strip() for item in items if item.strip())


def _missing(journey, keys):
    absent = [key for key in keys if not journey.get(key)]
    return ', '.join(absent)


def _ration_report(rations):
    measured = []
    for index, ration in enumerate(rations, start=1):
        measured.append(''.join(['Day ', str(index), ': ', ration.strip()]))
    return ', '.join(measured)


def _scout_report(reports):
    numbered = []
    for index, report in enumerate(reports, start=1):
        numbered.append(''.join(['(', str(index), ') ', report.strip()]))
    return ', '.join(numbered)


def caravan(journey):
    keys = [
        'oasis_stops',
        'camel_breeds',
        'trade_goods',
        'star_navigations',
        'weather_hazards',
        'tribe_alliances',
        'water_rations',
        'scout_reports',
    ]
    gaps = _missing(journey, keys)
    if gaps:
        return ''.join(['Incomplete route plan, missing: ', gaps])

    lines = [
        ''.join(['Oasis Route: ', _arrow_path(journey['oasis_stops'])]),
        ''.join(['Camel Breeds: ', _listing(journey['camel_breeds'])]),
        ''.join(['Trade Goods: ', _listing(journey['trade_goods'])]),
        ''.join(['Star Navigation: ', _arrow_path(journey['star_navigations'])]),
        ''.join(['Weather Hazards: ', _listing(journey['weather_hazards'])]),
        ''.join(['Tribe Alliances: ', _listing(journey['tribe_alliances'])]),
        ''.join(['Water Rations: ', _ration_report(journey['water_rations'])]),
        ''.join(['Scout Reports: ', _scout_report(journey['scout_reports'])]),
