ROW_KEYS = ('basic', 'decreases', 'lace', 'cables', 'bobbles', 'borders')

def _validate_row(row, index):
    unknown = [key for key in row if key not in ROW_KEYS]
    if unknown:
        listed = ', '.join(sorted(unknown))
        raise ValueError(''.join(['row ', str(index), ' uses unknown keys: ', listed]))

def basic_stitches(stitches):
    return ', '.join(stitches)

def decrease_group(decreases):
    return '-'.join(decreases)

def lace_pattern(moves):
    return '*'.join(moves)

def cable_cross(crosses):
    return '/'.join(crosses)

def bobble_cluster(counts):
    return '+'.join([str(count) for count in counts])

def border_edges(edges):
    return '|'.join(edges)

FORMATTERS = {
    'basic': basic_stitches,
    'decreases': decrease_group,
    'lace': lace_pattern,
    'cables': cable_cross,
    'bobbles': bobble_cluster,
    'borders': border_edges,
}

def format_row(row, index=1):
    _validate_row(row, index)
    pieces = []
    for key in ROW_KEYS:
        rendered = FORMATTERS[key](row.get(key, []))
        if rendered:
            pieces.append(rendered)
    return ' '.join(pieces)

def format_section(rows):
    return '; '.join([format_row(row, i) for i, row in enumerate(rows, 1)])

def summarize(garment):
    parts = [''.join(['section ', str(i), ': ', str(len(rows)), ' row(s)'])
             for i, rows in enumerate(garment, 1)]
    return ', '.join(parts)

def knit(garment):
    return '\n\n'.join([format_section(rows) for rows in garment])

