def format_recipe(recipe):
    """One quick reference line: seven components separated by pipes."""
    validate_recipe(recipe)
    return '|'.join([
        format_glassware(recipe['glassware']),
        format_spirits(recipe['spirits']),
        '&'.join(recipe['juices']),
        ','.join(recipe['syrups']),
        ' '.join(recipe['liqueurs']),
        format_bitters(recipe['bitters']),
        '+'.join(recipe['garnish']),
    ])


