FIELD_NAMES = [
    'tube lengths', 'joint angles', 'braze locations', 'cable routes',
    'fork dimensions', 'bracket standards', 'tire clearances', 'paint layers',
]


def _texts(values):
    return [str(value) for value in values]


def _validate(frame, index):
    if len(frame) != 8:
        found = str(len(frame))
        raise ValueError('Frame ' + str(index) + ' needs 8 sections, found ' + found)
    bad = [name for name, part in zip(FIELD_NAMES, frame)
           if not isinstance(part, (list, tuple))]
    if bad:
        detail = ''
        for _i, _p in enumerate(bad):
            if _i:
                detail += ', '
            detail += _p
        raise ValueError('Frame ' + str(index) + ' has non-list sections: ' + detail)


def format_tubing(tube_lengths, joint_angles, fork_dimensions):
    lengths = ''
    for _i, _p in enumerate(_texts(tube_lengths)):
        if _i:
            lengths += ', '
        lengths += _p
    angles = ''
    for _i, _p in enumerate(_texts(joint_angles)):
        if _i:
            angles += '-'
        angles += _p
