def _check_session(index, session):
    """Raise a descriptive error when a session tuple is malformed."""
    if len(session) != 5:
        expected = FIELD_NAMES[0] + ', ' + FIELD_NAMES[1] + ', ' + FIELD_NAMES[2] + ', ' + FIELD_NAMES[3] + ', ' + FIELD_NAMES[4]
        raise ValueError('session ' + str(index) + ' must hold: ' + expected)
