        raise ValueError('session ' + str(index) + ' has no ' + listed)


def _format_block(session):
    """Turn one session tuple into its four-line performance block."""
    _name, strikes, rests, chants, dynamics = session
    strike_line = ''
    for _i, item in enumerate(strikes):
        if _i:
            strike_line = strike_line + '-'
        strike_line = strike_line + str(item)
