    dynamic_line = ''
    for _i, item in enumerate(dynamics):
        if _i:
            dynamic_line = dynamic_line + '+'
        dynamic_line = dynamic_line + str(item)
    return strike_line + '\n' + rest_line + '\n' + chant_line + '\n' + dynamic_line


