def split_entry(text):
    """Separate an entry's name from its optional metadata tags."""
    name_part, _, tag_part = text.partition('|')
    tags = [tag.strip() for tag in tag_part.split(',') if tag.strip()]
    return name_part.strip(), tags


def file_label(text):
    """Return the printable label for a file entry and its extension."""
    name, tags = split_entry(text)
    if '.' in name:
        stem, extension = name.rsplit('.', 1)
        display = '.'.join([stem, extension])
    else:
        stem, extension = name, ''
        display = stem
    if not stem:
        raise ValueError('file entry without a name')
    if tags:
        suffix = ', '.join(tags)
        display = ''.join([display, ' [', suffix, ']'])
    return display, extension


def folder_label(text):
    """Return the printable label for a folder node."""
    name, tags = split_entry(text)
    if not name:
        raise ValueError('folder entry without a name')
    label = ''.join([name, '/'])
    if tags:
        suffix = ', '.join(tags)
        return ''.join([label, ' [', suffix, ']'])
    return label


def render(items, ancestors, lines, extensions):
    """Append one tree line per entry, recursing into nested folders."""
    total = len(items)
    for index, item in enumerate(items):
        last = index == total - 1
        prefix = ''.join(ancestors + ['└── ' if last else '├── '])
        if isinstance(item, list):
            if not item:
                raise ValueError('folder node must start with a name')
            lines.append(''.join([prefix, folder_label(item[0])]))
            render(item[1:], ancestors + ['    ' if last else '│   '], lines, extensions)
        elif isinstance(item, str):
            label, extension = file_label(item)
            lines.append(''.join([prefix, label]))
            if extension:
                extensions.add(extension)
        else:
            raise TypeError('tree entries must be strings or nested lists')


def summarize(extensions):
    """Build the one-line inventory of every extension in the tree."""
    if not extensions:
        return 'extensions: none'
    listing = ' '.join(sorted(extensions))
    return ''.join(['extensions: ', listing])


def visualize(hierarchy):
    """Render nested lists of folders and files as a textual tree block."""
    if not isinstance(hierarchy, list):
        raise TypeError('hierarchy must be a list')
    lines = []
    extensions = set()
    render(hierarchy, [], lines, extensions)
    tree = '\n'.join(lines)
    return '\n'.join([tree, '', summarize(extensions)])


