def format_identifier(component):
    """Build the component reference, e.g. prefix 'R' and id 3 -> 'R3'."""
    return ''.join([component['prefix'], str(component['id'])])


def format_value(component):
    """Build the value string from magnitude and unit, e.g. '10' + 'kOhm'."""
    return ''.join([str(component['magnitude']), component['unit']])


def format_nodes(component):
    """Wiring nodes of one component, separated by single spaces."""
    return ' '.join(str(node) for node in component['nodes'])


def describe_component(component):
    """One netlist line: identifier, value and node list."""
    return ' '.join([
        format_identifier(component),
        format_value(component),
        format_nodes(component),
    ])


def validate(components):
    """Reject components with missing fields or fewer than two nodes."""
    problems = []
    for index, component in enumerate(components):
        missing = [field for field in REQUIRED_FIELDS if field not in component]
        if missing:
            problems.append('component %d lacks %s' % (index, ', '.join(missing)))
        elif len(component['nodes']) < 2:
            problems.append('%s has too few nodes' % format_identifier(component))
    if problems:
        raise ValueError('; '.join(problems))


def group_by_type(components):
    """Map each prefix letter to the block of its description lines."""
    order = []
    lines_by_prefix = {}
    for component in components:
        prefix = component['prefix']
        if prefix not in lines_by_prefix:
            order.append(prefix)
            lines_by_prefix[prefix] = []
        lines_by_prefix[prefix].append(describe_component(component))
    return [('\n'.join(lines_by_prefix[prefix])) for prefix in order]


def format_date(date):
    """Date header as year/month/day."""
    year, month, day = date
    return '/'.join([str(year), str(month).zfill(2), str(day).zfill(2)])


def compile(circuit):
    components = circuit['components']
    validate(components)
    header = ''.join(['* netlist generated ', format_date(circuit['date'])])
    blocks = group_by_type(components)
    return '\n\n'.join([header] + blocks + ['.end'])


