            order.append(prefix)
            lines_by_prefix[prefix] = []
        lines_by_prefix[prefix].append(describe_component(component))
    blocks = []
    for prefix in order:
        block = ''
        for position, line in enumerate(lines_by_prefix[prefix]):
            if position:
                block = block + '\n'
            block = block + line
        blocks.append(block)
    return blocks


