import sys

FONT = {
    'A': '.X.X.XXXXX.XX.X', 'B': 'XX.X.XXX.X.XXX.', 'C': '.XXX..X..X...XX',
    'D': 'XX.X.XX.XX.XXX.', 'E': 'XXXX..XXXX..XXX', 'F': 'XXXX..XXXX..X..',
    'G': '.XXX..X.XX.X.XX', 'H': 'X.XX.XXXXX.XX.X', 'I': 'XXX.X..X..X.XXX',
    'J': '..X..X..XX.X.XX', 'K': 'X.XX.XXX.X.XX.X', 'L': 'X..X..X..X..XXX',
    'M': 'X.XXXXXXXX.XX.X', 'N': 'XX.X.XX.XX.XX.X', 'O': '.X.X.XX.XX.X.X.',
    'P': 'XX.X.XXX.X..X..', 'Q': '.X.X.XX.XXXX..X', 'R': 'XX.X.XXX.X.XX.X',
    'S': '.XXX...X...XXX.', 'T': 'XXX.X..X..X..X.', 'U': 'X.XX.XX.XX.XXXX',
    'V': 'X.XX.XX.XX.X.X.', 'W': 'X.XX.XXXXXXXX.X', 'X': 'X.XX.X.X.X.XX.X',
    'Y': 'X.XX.X.X..X..X.', 'Z': 'XXX..X.X.X..XXX',
}
GLYPH_WIDTH = 3
GLYPH_HEIGHT = 5
ON, OFF = '#', ' '


def letter_rows(ch):
    glyph = FONT[ch]
    return [''.join([ON if dot == 'X' else OFF
                     for dot in glyph[i * GLYPH_WIDTH:(i + 1) * GLYPH_WIDTH]])
            for i in range(GLYPH_HEIGHT)]


def word_block(word):
    glyphs = [letter_rows(ch) for ch in word]
    rows = []
    for i in range(GLYPH_HEIGHT):
        rows.append('  '.join([glyph[i] for glyph in glyphs]))
    return '\n'.join(rows)


def caption(text):
    spaced_words = [' '.join(word) for word in text.upper().split()]
    return '   '.join(spaced_words)


def unsupported(text):
    return sorted({ch for ch in text.upper() if not ch.isspace() and ch not in FONT})


def render(text):
    missing = unsupported(text)
    if missing:
        detail = ', '.join(missing)
        raise ValueError('cannot render these characters: ' + detail)
    words = text.upper().split()
    if not words:
        raise ValueError('cannot render an empty phrase')
    blocks = [word_block(word) for word in words]
    body = '\n\n'.join(blocks)
