def _minutes(snapshots):
    return ', '.join(str(snap['minute']) for snap in snapshots)


def _ascent(snapshots):
    return '<'.join(str(snap['depth']) for snap in snapshots)


def _stops(snapshots):
    return '-'.join(str(snap['pause']) for snap in snapshots)


def _gases(snapshots):
    return ':'.join(str(snap['gas']) for snap in snapshots)


def _heartrates(snapshots):
    return '~'.join(str(snap['heartrate']) for snap in snapshots)


def _temperatures(snapshots):
    return '+'.join(str(snap['temperature']) for snap in snapshots)


def _buoyancy(snapshots):
    return '|'.join(str(snap['buoyancy']) for snap in snapshots)


FIELDS = ('minute', 'depth', 'pause', 'gas', 'heartrate', 'temperature', 'buoyancy')


def validate(snapshots):
    for index, snap in enumerate(snapshots):
        missing = [field for field in FIELDS if field not in snap]
        if missing:
            raise ValueError(''.join([
                'snapshot ', str(index), ' is missing: ', ', '.join(missing)]))


def diveplan(depths):
    validate(depths)
    sections = [
        ''.join(['Bottom time: ', _minutes(depths)]),
        ''.join(['Ascent profile: ', _ascent(depths)]),
        ''.join(['Safety stops: ', _stops(depths)]),
        ''.join(['Gas mixture: ', _gases(depths)]),
        ''.join(['Heart rate: ', _heartrates(depths)]),
        ''.join(['Water temperature: ', _temperatures(depths)]),
        ''.join(['Buoyancy adjustments: ', _buoyancy(depths)]),
    ]
    return '\n'.join(sections)


