def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    return float(celsius) * 9 / 5 + 32


def parse_temperatures(text):
    """Parse a comma separated list of Celsius readings into floats."""
    values = []
    for token in text.split(','):
        token = token.strip()
        if token:
            try:
                values.append(float(token))
            except ValueError:
                raise ValueError(''.join(['not a number: ', token]))
    if not values:
        raise ValueError('no readings given')
    return values


def format_reading(celsius):
    """Render one reading as '25.0C = 77.0F'."""
    return ''.join(['{0:.1f}C = '.format(celsius), '{0:.1f}F'.format(celsius_to_fahrenheit(celsius))])


def describe(celsius):
    """Short human readable label for a Celsius reading."""
    if celsius >= 100:
        return 'boiling'
    if celsius >= 30:
        return 'hot'
    if celsius >= 15:
        return 'mild'
    if celsius > 0:
        return 'cool'
    return 'freezing'


def format_row(cells, widths):
    """Render one table row with pipe separated, left aligned cells."""
    return ''.join(['| ', cells[0].ljust(widths[0]), ' | ', cells[1].ljust(widths[1]), ' | ', cells[2].ljust(widths[2]), ' |'])


def format_divider(widths):
    """Render the horizontal rule matching the given column widths."""
    return ''.join(['+-', '-' * widths[0], '-+-', '-' * widths[1], '-+-', '-' * widths[2], '-+'])


def build_table(celsius_values):
    """Render a Celsius/Fahrenheit conversion table as a list of lines."""
    header = ('Celsius', 'Fahrenheit', 'Notes')
    rows = []
    for celsius in celsius_values:
        rows.append((
            '{0:.1f}'.format(celsius),
            '{0:.1f}'.format(celsius_to_fahrenheit(celsius)),
            describe(celsius),
        ))
    widths = [len(title) for title in header]
    for row in rows:
        widths = [max(width, len(cell)) for width, cell in zip(widths, row)]
    divider = format_divider(widths)
    lines = [divider, format_row(header, widths), divider]
    for row in rows:
        lines.append(format_row(row, widths))
    lines.append(divider)
    return lines


def summarize(celsius_values):
    """One line summary of the coldest, hottest and average readings."""
    coldest = ''.join(['coldest ', format_reading(min(celsius_values))])
    hottest = ''.join(['hottest ', format_reading(max(celsius_values))])
    average = ''.join(['average ', format_reading(sum(celsius_values) / len(celsius_values))])
    return ', '.join([coldest, hottest, average])


def main():
    raw = '-40, -17.8, 0, 16, 25, 37, 100'
    values = parse_temperatures(raw)
    print(''.join(['Input (C): ', raw]))
    for line in build_table(values):
        print(line)
    print(summarize(values))


if __name__ == '__main__':
    main()

