def validate_meeting(meeting, label):
    """Check that a meeting looks like (start, end) with start <= end."""
    if not isinstance(meeting, tuple) or len(meeting) != 2:
        raise ValueError(''.join([label, " must be a tuple of (start, end)"]))
    start, end = meeting
    if not all(isinstance(value, int) for value in (start, end)):
        raise ValueError(''.join([label, " must contain integer times"]))
    if start > end:
        raise ValueError(''.join([label, " ends before it starts: ", str(start), " > ", str(end)]))
    return start, end


def format_time(minutes):
    """Render a time given in minutes since midnight as HH:MM."""
    hours, mins = divmod(minutes, 60)
    return ''.join([str(hours).zfill(2), ":", str(mins).zfill(2)])


def format_meeting(meeting):
    """Render an interval as a readable HH:MM-HH:MM range."""
    start, end = meeting
    return ''.join([format_time(start), "-", format_time(end)])


def has_overlap(meeting1, meeting2):
    """Return True when the two meeting intervals share any time."""
    start1, end1 = validate_meeting(meeting1, "meeting1")
    start2, end2 = validate_meeting(meeting2, "meeting2")
    return start1 < end2 and start2 < end1


def overlap_window(meeting1, meeting2):
    """Return the shared interval, or None if the meetings do not overlap."""
    if not has_overlap(meeting1, meeting2):
        return None
    return max(meeting1[0], meeting2[0]), min(meeting1[1], meeting2[1])


def find_conflicts(schedule):
    """Collect every pair of named meetings in the schedule that overlaps."""
    conflicts = []
    for index, (name1, slot1) in enumerate(schedule):
        for name2, slot2 in schedule[index + 1:]:
            window = overlap_window(slot1, slot2)
            if window is not None:
                conflicts.append((name1, name2, window))
    return conflicts


def describe_conflict(name1, name2, window):
    """Describe a single clash between two named meetings."""
    return ''.join([name1, " clashes with ", name2, " during ", format_meeting(window)])


def summarize(schedule):
    """Build the report lines for a schedule and the clashes it contains."""
    lines = [''.join(["Meetings: ", str(len(schedule))])]
    for name, slot in schedule:
        lines.append(''.join(["  ", name, ": ", format_meeting(slot)]))
    conflicts = find_conflicts(schedule)
    lines.append(''.join(["Conflicts: ", str(len(conflicts))]))
    for item in conflicts:
        lines.append(''.join(["  ", describe_conflict(*item)]))
    return lines


def main():
    print(has_overlap((1, 5), (3, 7)))
    print(has_overlap((1, 2), (3, 4)))
    schedule = [
        ("standup", (9 * 60, 9 * 60 + 15)),
        ("design review", (9 * 60 + 10, 10 * 60)),
        ("lunch", (12 * 60, 13 * 60)),
        ("retro", (9 * 60 + 45, 10 * 60 + 30)),
    ]
    for line in summarize(schedule):
        print(line)


if __name__ == "__main__":
    main()

