def is_palindromic_number(number):
    """Return True if the decimal digits of number read the same both ways."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an int")
    digits = str(abs(number))
    return digits == digits[::-1]


def digit_chain(number):
    """Show the digits of number as an arrow-separated chain."""
    return ' -> '.join(list(str(abs(number))))


def mirror_halves(number):
    """Describe how the two halves of the number compare."""
    digits = str(abs(number))
    middle = len(digits) // 2
    left = digits[:middle]
    right = digits[len(digits) - middle:][::-1]
    pivot = digits[middle] if len(digits) % 2 else ''
    parts = [part for part in (left, pivot, right) if part]
    return '[' + '|'.join(parts) + ']'


def describe(number):
    """One-line verdict for a single number."""
    verdict = "palindromic" if is_palindromic_number(number) else "not palindromic"
    fields = [str(number), digit_chain(number), mirror_halves(number), verdict]
    return ' | '.join(fields)


def next_palindrome(number):
    """Smallest integer strictly greater than number that is palindromic."""
    candidate = number + 1
    while not is_palindromic_number(candidate):
        candidate += 1
    return candidate


def palindromes_in_range(start, stop):
    """All palindromic numbers in the half-open interval [start, stop)."""
    return [value for value in range(start, stop) if is_palindromic_number(value)]


def report(numbers):
    """Multi-line report covering every number given."""
    lines = [describe(number) for number in numbers]
    failures = [number for number in numbers if not is_palindromic_number(number)]
    if failures:
        followups = ', '.join(str(next_palindrome(number)) for number in failures)
        lines.append("next palindromes after the failures: " + followups)
    return '\n'.join(lines)


def width_summary(limit):
    """Count palindromes below limit, grouped by how many digits they have."""
    widths = {}
    for value in palindromes_in_range(1, limit):
        widths.setdefault(len(str(value)), []).append(value)
    counts = '; '.join(str(width) + " digits: " + str(len(group))
                       for width, group in sorted(widths.items()))
    total = "total: " + str(sum(len(group) for group in widths.values()))
    return ' || '.join([counts, total])


def main():
    print(report([121, 123, 0, -7, 1221, 10, 9009, 12345]))
    small = palindromes_in_range(100, 200)
    print("palindromes between 100 and 199: " + ', '.join(str(v) for v in small))
    print(width_summary(1000))


if __name__ == "__main__":
    main()

