                current_word = []
            word_parts.append(char)
        else:
            current_word.append(char)

    if current_word:
        word_parts.append(''.join(current_word))

    processed_words = []
    temp_word_buffer = []
    for part in word_parts:
        if part.isspace():
            if temp_word_buffer:
                processed_words.append(''.join(temp_word_buffer))
                temp_word_buffer = []
            processed_words.append(part)
        else:
            temp_word_buffer.append(part)
    if temp_word_buffer:
        processed_words.append(''.join(temp_word_buffer))

    final_words = []
    current_word_pieces = []

    for item in processed_words:
        if item.strip() == '':
            if current_word_pieces:
                final_words.append(''.join(current_word_pieces))
                current_word_pieces = []
            final_words.append(item)
        else:
            current_word_pieces.append(item)
    if current_word_pieces:
        final_words.append(''.join(current_word_pieces))

    pure_words_and_spaces = []
    current_segment = []
    for fw in final_words:
        if fw.strip() == '':
            if current_segment:
                pure_words_and_spaces.append(''.join(current_segment))
                current_segment = []
            pure_words_and_spaces.append(fw)
        else:
            current_segment.append(fw)
    if current_segment:
        pure_words_and_spaces.append(''.join(current_segment))

    words_only = [p for p in pure_words_and_spaces if p.strip() != '']
    spaces_only = [p for p in pure_words_and_spaces if p.strip() == '']

    if not words_only:
        return ''.join(spaces_only)

    reversed_words = words_only[::-1]

    result_parts = []
    for i in range(len(reversed_words)):
        result_parts.append(reversed_words[i])
        if i < len(spaces_only):
            result_parts.append(spaces_only[i])

    if len(reversed_words) > len(spaces_only):
        trailing_spaces_index = len(spaces_only)
        if trailing_spaces_index < len(pure_words_and_spaces) and pure_words_and_spaces[trailing_spaces_index].strip() == '':
            result_parts.append(''.join(pure_words_and_spaces[trailing_spaces_index:]))

    return ''.join(result_parts).strip()

