from datetime import date


def _validate(description, amount, date_str):
    problems = []
    if not isinstance(description, str) or not description.strip():
        problems.append('description must be a non-empty string')
    try:
        amount = float(amount)
    except (TypeError, ValueError):
        problems.append('amount must be a number')
    else:
        if amount < 0:
            problems.append('amount must not be negative')
    try:
        parts = date_str.split('-')
        date(int(parts[0]), int(parts[1]), int(parts[2]))
    except (AttributeError, IndexError, ValueError):
        problems.append('date must be in YYYY-MM-DD format')
    if problems:
        raise ValueError('; '.join(problems))
    return amount


def record_expense(expenses, description, amount, date_str):
