def proper_divisors(num):
    """Return the sorted proper positive divisors of num."""
    if num < 1:
        raise ValueError("num must be a positive integer")
    divisors = {1} if num > 1 else set()
    step = 2
    while step * step <= num:
        if num % step == 0:
            divisors.add(step)
            partner = num // step
            if partner != num:
                divisors.add(partner)
        step += 1
    return sorted(divisors)


def is_perfect_number(num):
    """True when num equals the sum of its proper positive divisors."""
    return num > 1 and sum(proper_divisors(num)) == num


def divisor_sum_expression(divisors):
    """Render a divisor sum as an arithmetic expression."""
    if not divisors:
        return "0"
    return ' + '.join(str(d) for d in divisors)


def classify(num):
    """Label num as perfect, abundant or deficient."""
    total = sum(proper_divisors(num))
    if total == num:
        return "perfect"
    return "abundant" if total > num else "deficient"


def describe(num):
    """One-line description of num's divisor structure."""
    divisors = proper_divisors(num)
    listing = ', '.join(str(d) for d in divisors) if divisors else "none"
    return ''.join([
        str(num).rjust(5),
        "  ",
        classify(num).ljust(9),
        " divisors: ",
        listing,
        " -> ",
        divisor_sum_expression(divisors),
        " = ",
        str(sum(divisors)),
    ])


def report(numbers):
    """Build a multi-line report for the given numbers."""
    header = "  num  classification and divisor sum"
    lines = [header, "-" * len(header)]
    lines.extend(describe(n) for n in numbers)
    perfect = [str(n) for n in numbers if is_perfect_number(n)]
    found = ', '.join(perfect) if perfect else "none"
    lines.append("perfect numbers found: " + found)
    return '\n'.join(lines)


def main():
    print(report([1, 6, 12, 28, 97, 100, 496, 8128]))


if __name__ == "__main__":
    main()

