class Node:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

    def __repr__(self):
        parts = [str(self.value)]
        if self.left is not None or self.right is not None:
            parts.append('(')
            acc = ''
            first = True
            for child in (self.left, self.right):
                if first:
                    acc = acc + (repr(child) if child else '.')
                    first = False
                else:
                    acc = acc + ', ' + (repr(child) if child else '.')
            parts.append(acc)
            parts.append(')')
        result = ''
        for part in parts:
            result = result + part
        return result


def build_tree(values):
    """Build a binary tree from a level-order list where None means 'no node'."""
    nodes = [None if v is None else Node(v) for v in values]
    children = iter(nodes[1:])
    for node in nodes:
        if node is None:
            continue
        node.left = next(children, None)
        node.right = next(children, None)
    return nodes[0] if nodes else None


def level_order(root):
    """Return the level-order values of the tree, trailing empty slots trimmed."""
    if root is None:
        return []
    values, queue = [], [root]
    while queue:
        node = queue.pop(0)
        if node is None:
            values.append(None)
            continue
        values.append(node.value)
        queue.extend([node.left, node.right])
    while values and values[-1] is None:
        values.pop()
    return values


def format_level_order(root):
    acc = ''
    first = True
    for v in level_order(root):
        if first:
            acc = acc + ('null' if v is None else str(v))
            first = False
        else:
            acc = acc + ', ' + ('null' if v is None else str(v))
    return acc


def is_symmetric(root):
    """True if the tree is a mirror image of itself."""
    if root is None:
        return True
    pairs = [(root.left, root.right)]
    while pairs:
        left, right = pairs.pop()
        if left is None and right is None:
            continue
        if left is None or right is None or left.value != right.value:
            return False
        pairs.append((left.left, right.right))
        pairs.append((left.right, right.left))
    return True


def describe(values):
    root = build_tree(values)
    verdict = 'symmetric' if is_symmetric(root) else 'not symmetric'
    return '[' + format_level_order(root) + '] -> ' + verdict + \
        '  shape: ' + (repr(root) if root else 'empty')


def main():
    cases = [
        [1, 2, 2, 3, 4, 4, 3],
        [1, 2, 2, None, 3, None, 3],
        [],
        [7],
        [1, 2, 2, None, None, None, None],
    ]
    acc = ''
    first = True
    for values in cases:
        if first:
            acc = acc + describe(values)
            first = False
        else:
            acc = acc + '\n' + describe(values)
    print(acc)


if __name__ == '__main__':
    main()

