def _signature(word: str) -> str:
    """Canonical anagram key: the word's letters, lowercased and sorted."""
    return ''.join(sorted(word.lower()))


def _check_words(words: list[str]) -> None:
    """Reject inputs that are not a list of strings, naming every offender."""
    if not isinstance(words, list):
        raise TypeError("group_anagrams expects a list of strings")
    offenders = [
        "index {0} is {1}".format(i, type(w).__name__)
        for i, w in enumerate(words)
        if not isinstance(w, str)
    ]
    if offenders:
        detail = ', '.join(offenders)
        raise TypeError("non-string entries: " + detail)


def group_anagrams(words: list[str]) -> list[list[str]]:
    """Group words that are anagrams of each other, ignoring letter case."""
    _check_words(words)
    buckets: dict[str, list[str]] = {}
    for word in words:
        buckets.setdefault(_signature(word), []).append(word)
    return list(buckets.values())


def format_group(group: list[str]) -> str:
    """Render one anagram group as a readable, alphabetically ordered line."""
    return ', '.join(sorted(group, key=str.lower))


def letter_profile(word: str) -> str:
    """Compact letter histogram, e.g. 'listen' -> 'e1i1l1n1s1t1'."""
    signature = _signature(word)
    counts = [letter + str(signature.count(letter)) for letter in sorted(set(signature))]
    return ''.join(counts)


def summarize(groups: list[list[str]]) -> str:
    """One-line summary of how many groups were found and how big they are."""
    sizes = sorted((len(group) for group in groups), reverse=True)
    size_text = ', '.join(str(n) for n in sizes)
    return "{0} group(s), sizes {1}".format(len(groups), size_text)


def format_report(words: list[str]) -> str:
    """Full report: one line per group, biggest groups first, plus a summary."""
    groups = group_anagrams(words)
    ordered = sorted(groups, key=lambda group: (-len(group), format_group(group)))
    lines = []
    for group in ordered:
        lines.append("  [{0}] {1}".format(letter_profile(group[0]), format_group(group)))
    lines.append("  " + summarize(groups))
    return '\n'.join(lines)


def main() -> None:
    samples = [
        ['eat', 'tea', 'tan', 'ate', 'nat', 'bat'],
        ['listen', 'silent', 'hello'],
        ['Dusty', 'Study', 'Night', 'Thing', 'STUDY'],
    ]
    for words in samples:
        heading = ', '.join(words)
        print("input: " + heading)
        print(format_report(words))
        print()


if __name__ == '__main__':
    main()

