def power_recursive(base: float, exponent: int) -> float:
    """Return base ** exponent for a non-negative integer exponent."""
    if not isinstance(exponent, int) or isinstance(exponent, bool):
        raise TypeError("exponent must be a plain non-negative integer")
    if exponent < 0:
        raise ValueError("exponent must be non-negative")
    if exponent == 0:
        return 1.0
    half = power_recursive(base, exponent // 2)
    if exponent % 2 == 0:
        return half * half
    return base * half * half


def format_number(value: float) -> str:
    """Render a float without a trailing '.0' when it is integral."""
    if value == int(value):
        return str(int(value))
    return repr(value)


def expansion(base: float, exponent: int) -> str:
    """Write the power as a product of factors, e.g. '2 * 2 * 2'."""
    if exponent == 0:
        return "1"
    return ' * '.join([format_number(base)] * exponent)


def squaring_steps(exponent: int) -> str:
    """Describe the exponents visited by the recursion, largest first."""
    steps = []
    current = exponent
    while current > 0:
        steps.append(str(current))
        current //= 2
    steps.append("0")
    return ' -> '.join(steps)


def describe(base: float, exponent: int) -> str:
    """Render one full line: the power, its expansion and its value."""
    result = power_recursive(base, exponent)
    return ''.join([
        format_number(base),
        "^",
        str(exponent),
        " = ",
        expansion(base, exponent),
        " = ",
        format_number(result),
    ])


def report(cases) -> str:
    """Build a multi-line report for a sequence of (base, exponent) pairs."""
    lines = ["POWERS BY RECURSION", "=" * 19]
    for base, exponent in cases:
        lines.append(describe(base, exponent))
        lines.append("    exponents: " + squaring_steps(exponent))
    summary = ', '.join(format_number(b) + "^" + str(e) for b, e in cases)
    lines.append("computed: " + summary)
    return '\n'.join(lines)


def main() -> None:
    cases = [(2, 3), (5, 0), (1.5, 4), (3, 7), (-2, 5)]
    print(report(cases))


if __name__ == "__main__":
    main()

